# Датированная выборка опубликованных правил; не physical flight inventory.
weekdays={'Пн':0,'Вт':1,'Ср':2,'Чт':3,'Пт':4,'Сб':5,'Вс':6};samples=[]
for r in rules:
    try:a=datetime.strptime(r['valid_from'],'%d.%m.%Y').date();b=datetime.strptime(r['valid_to'],'%d.%m.%Y').date()
    except ValueError:continue
    days=[n for t,n in weekdays.items() if t in r['weekdays_or_date']]
    for lo in [date(2026,11,16),date(2026,12,7),date(2027,3,1)]:
        for off in range(7):
            d=lo+timedelta(days=off)
            if a<=d<=b and (d.weekday() in days if days else a==b==d):samples.append(dict(sample_week=str(lo),departure_date=str(d),origin='KZN',destination=r['destination'],flight=r['flight'],shared_flight_names=r['shared_flight_names'],departure_local=r['departure_local'],source_id=r['source_id'],source_row_id=r['source_row_id'],period=str(d),unit='published_departure_occurrence',coverage='3специальновыбранныенедели;неполныйгод',status='PUBLISHED_RULE_EXPANSION_NOT_INVENTORY',source_sha256=r['source_sha256']))
table('dated_published_samples.csv',samples)
